text:
        fragments.AppendElement(nsFmtCString("{},{}", first, last));
        break;
      default:
        fragments.AppendElement(nsFmtCString("{}:{}", first, last));
        break;
    }
  }

  return StringJoin(","_ns, fragments);
}

